# Simpler: explicit ORF extraction frame by frame
def orfs_in_frame(s, frame):
    res = []
    i = frame
    seg_start = frame
    while i + 3 <= len(s):
        if s[i:i+3] in stops:
            seg = s[seg_start:i]         # codons before stop
            res.append((seg_start, i, seg))
            i += 3
            seg_start = i
        else:
            i += 3
    if seg_start < len(s) - 2:
        res.append((seg_start, len(s) - ((len(s)-seg_start) % 3), s[seg_start:]))
    return res

