            os_,oe = (k+1, min(b+3,N)) if hasstart else (None,None)
        else:
            fs,fe = N-b+1, N-a
            os_,oe = (N-b+1, N-k) if hasstart else (None,None)
        out.append((fs,fe,a,b,hasstart,os_,oe, s[a:b+3]))
