def rc(s): return s.translate(str.maketrans("ACGT","TGCA"))[::-1]
stops=set('TAA TAG TGA'.split())

def find_atg_orfs(s, strand, minlen=60):
    out=[]
    for frame in range(3):
        j=frame
        while j+3<=len(s):
            if s[j:j+3] in stops:
                b=j
                # stop-to-start: leftmost ATG in the segment [a,b]; but we don't have a here.
                j+=3
            else:
                j+=3
    # Alternative approach: iterate codons, maintain current ATG start (or None)
    # Do it with a simple longest-ATG-to-stop search per frame
    for frame in range(3):
        j=frame; a=frame
        while j+3<=len(s):
            if s[j:j+3] in stops:
                b=j
                segments=(b-a)//3
                if segments>=minlen:
                    atgs=[k for k in range(a,b-2,3) if s[k:k+3]=='ATG']
                    if atgs:
                        # longest ORF: smallest k on this strand (5' end)
                        k=atgs[0]
                        p=transl(s[k:b+3])[:-1]
                        if strand=='+':
                            fs=k+1; fe=N-b+3 if b+3<=N else N-b  # careful
                            fs=k+1
                            fe=k+ (b-k) +3   # stop ends at k+(b-k)+3-1 → 1-based fe
                        else:
                            fs=N-b+1
                            fe=N-k
                        out.append((fs,fe,len(p),p,strand,frame+1))
                a=j+3
            j+=3
        if a<len(s)-2:
            # trailing segment without stop
            atgs=[k for k in range(a,len(s)-2,3) if s[k:k+3]=='ATG']
            if atgs:
                k=atgs[0]
                p=transl(s[k:])[:-1]
                if strand=='+':
                    fs=k+1; fe=N
                else:
                    fs=1; fe=N-k
                out.append((fs,fe,len(p),p,strand,frame+1))
    return out

print("=== Longest ATG-initiated ORFs per strand (>=100 aa) ===")
for strand, s in [('+',seq), ('-',rc(seq))]:
